from fixtures import load_fixtures, ROWS
from ranking import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_fixtures()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_fixtures()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_fixtures()))
    assert [x.goals for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_fixtures())
    podium(data, 2)
    assert [x.goals for x in data] == VALUES


def test_one_place():
    assert [x.goals for x in podium(list(load_fixtures()), 1)] == [max(VALUES)]
